  +
  +export function isAuthorizationCodeOAuthProvider(
  +	providerId: OAuthProviderId,
  +): providerId is AuthorizationCodeOAuthProviderId {
  +	return providerId !== "github-copilot";
  +}
  +
  +export function getOAuthProviderConfig(
